$ErrorActionPreference = 'Stop'

$markerPath = 'E:\codex-LOOP\state\codex-loop-f2-wsl-complete.json'
$setupScript = 'E:\codex-LOOP\.bootstrap\complete-codex-loop-f2.ps1'

function Show-LoopMessage {
    param([string]$Text, [string]$Title = 'Codex LOOP F2')
    Add-Type -AssemblyName PresentationFramework
    [System.Windows.MessageBox]::Show($Text, $Title) | Out-Null
}

if (-not (Test-Path -LiteralPath $markerPath)) {
    $pendingRestart = (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') -or
        (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired')

    if ($pendingRestart) {
        Show-LoopMessage 'WSL2 is waiting for a Windows restart. Restart Windows, sign in, and double-click this shortcut again. It will continue the Ubuntu/F2 installation and run the full verification.'
        exit 10
    }

    $setup = Start-Process -FilePath 'powershell.exe' -Verb RunAs -ArgumentList @(
        '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $setupScript
    ) -PassThru -Wait

    if ($setup.ExitCode -ne 0 -or -not (Test-Path -LiteralPath $markerPath)) {
        Show-LoopMessage "F2 setup or verification is not complete. Check:`nE:\codex-LOOP\logs\codex-loop-f2-wsl-setup.log"
        exit 1
    }
}

$terminal = Get-Command wt.exe -ErrorAction SilentlyContinue
if ($terminal) {
    Start-Process -FilePath $terminal.Source -ArgumentList @(
        'wsl.exe', '-d', 'Ubuntu', '-u', 'codexloop', '--', '/home/codexloop/bin/start-codex-loop-f2'
    )
} else {
    Start-Process -FilePath 'wsl.exe' -ArgumentList @(
        '-d', 'Ubuntu', '-u', 'codexloop', '--', '/home/codexloop/bin/start-codex-loop-f2'
    )
}

[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('Activate', 'Deactivate', 'Status', 'Restore')]
    [string]$Mode
)

$ErrorActionPreference = 'Stop'
$root = 'E:\codex-LOOP\codex-loop-s-f2'
$tool = Join-Path $root 'harness\global_desktop_mode.py'
$python = 'E:\codex-LOOP\venv\Scripts\python.exe'
$codexHome = Join-Path $env:USERPROFILE '.codex'

if (-not (Test-Path -LiteralPath $python -PathType Leaf)) {
    $python = (Get-Command py.exe -ErrorAction Stop).Source
    $pythonArgs = @('-3')
}
else {
    $pythonArgs = @()
}

$action = switch ($Mode) {
    'Activate' { 'activate' }
    'Deactivate' { 'deactivate' }
    'Restore' { 'restore' }
    default { 'status' }
}

& $python @pythonArgs $tool $action --root $root --codex-home $codexHome
if ($LASTEXITCODE -ne 0) {
    throw "Codex LOOP global mode action failed: $Mode"
}

if ($Mode -eq 'Activate') {
    Write-Host 'LOOP mode is active for every newly started or resumed Desktop task, regardless of project.'
}
elseif ($Mode -eq 'Deactivate') {
    Write-Host 'LOOP mode is inactive. New or resumed Desktop tasks will not inherit LOOP orchestration.'
}
elseif ($Mode -eq 'Restore') {
    Write-Host 'The pre-install global AGENTS.md and hooks.json were restored from the verified backup.'
}

$ErrorActionPreference = 'Stop'
$url = 'http://127.0.0.1:8765/'
$health = 'http://127.0.0.1:8765/healthz'
$server = 'E:\codex-LOOP\launchers\loop_monitor_server.py'
$mutex = [System.Threading.Mutex]::new(
    $false, 'Local\Codex-LOOP-Monitor-8765-Start')
$hasMutex = $false

try {
    try {
        $hasMutex = $mutex.WaitOne([TimeSpan]::FromSeconds(15))
    } catch [System.Threading.AbandonedMutexException] {
        # WaitOne grants ownership before raising for an abandoned mutex.
        # Record that ownership so the outer finally always releases it.
        Write-Warning 'A previous monitor starter abandoned the startup lock; recovering.'
        $hasMutex = $true
    }
    if (-not $hasMutex) {
        throw 'Timed out waiting for the Codex LOOP monitor startup lock.'
    }
    try {
        $ready = (Invoke-RestMethod -Uri $health -TimeoutSec 1).status -eq 'ok'
    } catch {
        $ready = $false
    }

    if (-not $ready) {
        $preferredPython = 'C:\Users\hzq00\AppData\Local\Programs\Python\Python314\python.exe'
        $python = if (Test-Path -LiteralPath $preferredPython) {
            $preferredPython
        } else {
            (Get-Command python.exe -ErrorAction Stop).Source
        }
        Start-Process -FilePath $python -WindowStyle Hidden -ArgumentList @(
            $server, '--port', '8765'
        ) | Out-Null
        for ($i = 0; $i -lt 20 -and -not $ready; $i++) {
            Start-Sleep -Milliseconds 250
            try {
                $ready = (Invoke-RestMethod -Uri $health -TimeoutSec 1).status -eq 'ok'
            } catch {
                $ready = $false
            }
        }
    }

    if (-not $ready) {
        throw 'Codex LOOP monitor did not become ready on 127.0.0.1:8765.'
    }

    $url
} finally {
    if ($hasMutex) {
        $mutex.ReleaseMutex()
    }
    $mutex.Dispose()
}

param(
    [switch]$DryRun,
    [switch]$NoLaunch
)

$ErrorActionPreference = 'Stop'
$Root = Split-Path -Parent $PSScriptRoot
$RuntimeDir = Join-Path $Root 'state\desktop-runtime'
$Python = 'E:\codex-LOOP\venv\Scripts\python.exe'
$PythonW = 'E:\codex-LOOP\venv\Scripts\pythonw.exe'
$RuntimeTool = Join-Path $Root 'tools\desktop_loop_runtime.py'
$GateMonitor = Join-Path $Root 'tools\desktop_gate_monitor.py'
$HookTrustTool = Join-Path $Root 'tools\desktop_hook_trust.py'
$HookTrustManifest = Join-Path $Root 'deploy\desktop-hook-trust.json'
$GatewayProfilePath = Join-Path $Root 'deploy\gateway-profile.json'
$GlobalConfig = Join-Path $env:USERPROFILE '.codex\config.toml'
$AuthPath = Join-Path $env:USERPROFILE '.codex\auth.json'
$GlobalLoopModeTool = 'E:\codex-LOOP\codex-loop-s-f2\harness\global_desktop_mode.py'
$GlobalLoopControlRoot = 'E:\codex-LOOP\codex-loop-s-f2'
$Log = Join-Path $RuntimeDir 'launcher.log'
$ComponentReport = Join-Path $RuntimeDir 'startup-components.json'
$Gateway = $null

function Write-LauncherLog([string]$Message) {
    New-Item -ItemType Directory -Force -Path $RuntimeDir | Out-Null
    $line = '{0} {1}' -f ([DateTimeOffset]::Now.ToString('o')), $Message
    $encoding = New-Object System.Text.UTF8Encoding($false)
    $bytes = $encoding.GetBytes($line + [Environment]::NewLine)
    foreach ($attempt in 1..100) {
        $stream = $null
        try {
            $stream = New-Object System.IO.FileStream(
                $Log,
                [System.IO.FileMode]::Append,
                [System.IO.FileAccess]::Write,
                [System.IO.FileShare]::ReadWrite
            )
            $stream.Write($bytes, 0, $bytes.Length)
            $stream.Flush($true)
            return
        }
        catch [System.IO.IOException] {
            if ($attempt -lt 100) {
                Start-Sleep -Milliseconds 50
            }
        }
        finally {
            if ($null -ne $stream) {
                $stream.Dispose()
            }
        }
    }
    # Operational logging must not become a startup gate. Component reports,
    # hook trust reports, and runtime status remain the mechanical evidence.
}

function Show-LauncherError([string]$Message) {
    Write-LauncherLog "ERROR $Message"
    Add-Type -AssemblyName PresentationFramework
    [System.Windows.MessageBox]::Show(
        $Message,
        'Codex HL-LOOP startup failed',
        [System.Windows.MessageBoxButton]::OK,
        [System.Windows.MessageBoxImage]::Error
    ) | Out-Null
}

function Test-Gateway {
    $client = New-Object System.Net.Sockets.TcpClient
    try {
        $task = $client.ConnectAsync([string]$Gateway.host, [int]$Gateway.port)
        if (-not $task.Wait(700)) { return $false }
        if (-not $client.Connected) { return $false }
        $health = Invoke-RestMethod -Method Get -Uri ([string]$Gateway.health_url) -TimeoutSec 2
        return $health.status -eq $Gateway.health_identity.status `
            -and $health.service -eq $Gateway.health_identity.service `
            -and $health.version -eq $Gateway.health_identity.version `
            -and [int]$health.port -eq [int]$Gateway.port
    }
    catch { return $false }
    finally { $client.Dispose() }
}

function Assert-GatewayProfile {
    if ($Gateway.schema -ne 'hl-loop-gateway-profile/v1' -or $Gateway.gateway_id -ne 'opencodex') {
        throw 'Gateway profile schema or identity is invalid.'
    }
    if ($Gateway.host -ne '127.0.0.1' -or [int]$Gateway.port -ne 10100) {
        throw 'Gateway profile must use the reviewed OpenCodex loopback endpoint 127.0.0.1:10100.'
    }
    $pins = @(
        [pscustomobject]@{ path = [string]$Gateway.package.package_json; sha256 = [string]$Gateway.package.package_json_sha256 }
        [pscustomobject]@{ path = [string]$Gateway.package.cli_entry; sha256 = [string]$Gateway.package.cli_entry_sha256 }
        [pscustomobject]@{ path = [string]$Gateway.service.process_executable; sha256 = [string]$Gateway.service.process_executable_sha256 }
        [pscustomobject]@{ path = [string]$Gateway.service.launcher; sha256 = [string]$Gateway.service.launcher_sha256 }
        [pscustomobject]@{ path = [string]$Gateway.service.command; sha256 = [string]$Gateway.service.command_sha256 }
    )
    foreach ($pin in $pins) {
        if (-not (Test-Path -LiteralPath $pin.path -PathType Leaf)) {
            throw "Pinned OpenCodex file is missing: $($pin.path)"
        }
        $actual = (Get-FileHash -LiteralPath $pin.path -Algorithm SHA256).Hash.ToLowerInvariant()
        if ($actual -ne $pin.sha256) {
            throw "Pinned OpenCodex file hash mismatch: $($pin.path)"
        }
    }
}

function Test-ProcessId([int]$ProcessId) {
    if ($ProcessId -le 0) { return $false }
    return $null -ne (Get-Process -Id $ProcessId -ErrorAction SilentlyContinue)
}

function Get-LockOwner([string]$LockDirectory) {
    $pidPath = Join-Path $LockDirectory 'pid'
    if (-not (Test-Path -LiteralPath $pidPath)) { return 0 }
    try {
        $owner = [int](Get-Content -LiteralPath $pidPath -Raw).Trim()
        if (Test-ProcessId $owner) { return $owner }
    }
    catch { return 0 }
    return 0
}

function Wait-Sidecars {
    $supervisorLock = Join-Path $RuntimeDir 'supervisor.lock.dir'
    $monitorLock = Join-Path $RuntimeDir 'g3-monitor.lockdir'
    $statusPath = Join-Path $RuntimeDir 'runtime-status.json'
    foreach ($attempt in 1..40) {
        $supervisorPid = Get-LockOwner $supervisorLock
        $monitorPid = Get-LockOwner $monitorLock
        $runtimeReady = $false
        $runtimeHealthy = $false
        if (Test-Path -LiteralPath $statusPath) {
            try {
                $runtime = Get-Content -LiteralPath $statusPath -Raw | ConvertFrom-Json
                $reportedSupervisorPid = [int]$runtime.supervisor_pid
                $runtimeReady = $reportedSupervisorPid -eq $supervisorPid `
                    -and (Test-ProcessId $reportedSupervisorPid) `
                    -and $runtime.preflight_ok -eq $true `
                    -and $runtime.gateway.ok -eq $true
                $runtimeHealthy = $runtimeReady -and $runtime.healthy -eq $true
            }
            catch {
                $runtimeReady = $false
                $runtimeHealthy = $false
            }
        }
        if ($supervisorPid -gt 0 -and $monitorPid -gt 0 -and $runtimeReady) {
            return [pscustomobject]@{
                supervisor_pid = $supervisorPid
                gate_monitor_pid = $monitorPid
                runtime_healthy = $runtimeHealthy
            }
        }
        Start-Sleep -Milliseconds 500
    }
    throw 'LOOP supervisor and gate monitor did not publish a valid base snapshot within 20 seconds.'
}

function Wait-RuntimeHealthy([object]$Sidecars) {
    $supervisorLock = Join-Path $RuntimeDir 'supervisor.lock.dir'
    $monitorLock = Join-Path $RuntimeDir 'g3-monitor.lockdir'
    $statusPath = Join-Path $RuntimeDir 'runtime-status.json'
    $lastDetail = 'runtime status was unavailable'
    foreach ($attempt in 1..80) {
        $supervisorPid = Get-LockOwner $supervisorLock
        $monitorPid = Get-LockOwner $monitorLock
        if ($supervisorPid -ne [int]$Sidecars.supervisor_pid) {
            $lastDetail = "supervisor lock changed from $($Sidecars.supervisor_pid) to $supervisorPid"
        }
        elseif ($monitorPid -ne [int]$Sidecars.gate_monitor_pid) {
            $lastDetail = "gate monitor lock changed from $($Sidecars.gate_monitor_pid) to $monitorPid"
        }
        elseif (Test-Path -LiteralPath $statusPath) {
            try {
                $runtime = Get-Content -LiteralPath $statusPath -Raw | ConvertFrom-Json
                $reportedSupervisorPid = [int]$runtime.supervisor_pid
                $lastDetail = "reported_supervisor=$reportedSupervisorPid healthy=$($runtime.healthy) " + `
                    "preflight_ok=$($runtime.preflight_ok) gateway_ok=$($runtime.gateway.ok)"
                if (
                    $reportedSupervisorPid -eq $supervisorPid -and
                    (Test-ProcessId $reportedSupervisorPid) -and
                    $runtime.preflight_ok -eq $true -and
                    $runtime.gateway.ok -eq $true -and
                    $runtime.healthy -eq $true
                ) {
                    return [pscustomobject]@{
                        supervisor_pid = $supervisorPid
                        gate_monitor_pid = $monitorPid
                        runtime_healthy = $true
                    }
                }
            }
            catch {
                $lastDetail = "runtime status could not be parsed: $($_.Exception.Message)"
            }
        }
        Start-Sleep -Milliseconds 500
    }
    throw "Codex Desktop opened, but LOOP runtime did not become healthy within 40 seconds ($lastDetail)."
}

function Show-CodexDesktop {
    try {
        $package = Get-AppxPackage -Name 'OpenAI.Codex' -ErrorAction Stop
        $expectedExecutable = Join-Path $package.InstallLocation 'app\ChatGPT.exe'
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

public static class HlLoopDesktopWindow {
    [DllImport("user32.dll")]
    public static extern bool ShowWindowAsync(IntPtr hWnd, int nCmdShow);

    [DllImport("user32.dll")]
    public static extern bool SetForegroundWindow(IntPtr hWnd);
}
'@ -ErrorAction SilentlyContinue

        $deadline = [DateTimeOffset]::Now.AddSeconds(8)
        do {
            $window = Get-Process -Name 'ChatGPT' -ErrorAction SilentlyContinue |
                Where-Object {
                    $_.MainWindowHandle -ne 0 -and
                    $_.Path -eq $expectedExecutable
                } |
                Sort-Object StartTime -Descending |
                Select-Object -First 1
            if ($window) {
                # SW_RESTORE = 9. This also restores a minimized Codex window.
                [HlLoopDesktopWindow]::ShowWindowAsync($window.MainWindowHandle, 9) | Out-Null
                Start-Sleep -Milliseconds 150
                $shell = New-Object -ComObject WScript.Shell
                $activated = $shell.AppActivate($window.Id)
                if (-not $activated) {
                    $activated = [HlLoopDesktopWindow]::SetForegroundWindow($window.MainWindowHandle)
                }
                return [bool]$activated
            }
            Start-Sleep -Milliseconds 200
        } while ([DateTimeOffset]::Now -lt $deadline)
    }
    catch {
        Write-LauncherLog "WARNING Codex Desktop foreground activation failed: $($_.Exception.Message)"
    }
    return $false
}

function Write-ComponentReport([object]$Sidecars, [string]$DesktopState) {
    $payload = [ordered]@{
        schema = 'hl-loop-desktop-startup-components/v2'
        generated_at = [DateTimeOffset]::Now.ToString('o')
        root = $Root
        gateway = [ordered]@{
            id = [string]$Gateway.gateway_id
            listening = (Test-Gateway)
            endpoint = [string]$Gateway.base_url
            version = [string]$Gateway.health_identity.version
            profile = $GatewayProfilePath
            profile_sha256 = (Get-FileHash -LiteralPath $GatewayProfilePath -Algorithm SHA256).Hash.ToLowerInvariant()
        }
        persistent_sidecars = [ordered]@{
            runtime_supervisor = [ordered]@{ running = $Sidecars.supervisor_pid -gt 0; pid = $Sidecars.supervisor_pid }
            gate_monitor = [ordered]@{ running = $Sidecars.gate_monitor_pid -gt 0; pid = $Sidecars.gate_monitor_pid }
        }
        event_driven_hooks = [ordered]@{
            trust_verified = $true
            mode = 'spawned_by_codex_events_not_persistent'
            manifest = $HookTrustManifest
        }
        desktop = [ordered]@{ state = $DesktopState }
        healthy = (Test-Gateway) -and $Sidecars.runtime_healthy
    }
    $temporary = "$ComponentReport.$PID.tmp"
    $payload | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $temporary -Encoding UTF8
    Move-Item -LiteralPath $temporary -Destination $ComponentReport -Force
}

function Ensure-Gateway {
    Assert-GatewayProfile
    if (Test-Gateway) {
        Write-LauncherLog 'Pinned OpenCodex gateway already healthy on 127.0.0.1:10100'
        return
    }

    $taskName = [string]$Gateway.service.scheduled_task
    $scheduled = Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue
    if (-not $scheduled) {
        throw "Pinned OpenCodex scheduled task is missing: $taskName"
    }
    if ($scheduled.Settings.Enabled -ne $true -or $scheduled.State -eq 'Disabled') {
        throw "Pinned OpenCodex scheduled task is disabled: $taskName"
    }
    Start-ScheduledTask -TaskName $taskName

    foreach ($attempt in 1..20) {
        Start-Sleep -Milliseconds 500
        if (Test-Gateway) {
            Write-LauncherLog 'Pinned OpenCodex gateway started successfully'
            return
        }
    }
    throw 'Pinned OpenCodex gateway did not become healthy on 127.0.0.1:10100 within 10 seconds.'
}

function Get-DesktopAppServerCopy {
    $package = Get-AppxPackage -Name 'OpenAI.Codex' -ErrorAction Stop
    if (-not $package) { throw 'The OpenAI Codex Desktop package is not installed.' }
    $source = Join-Path $package.InstallLocation 'app\resources\codex.exe'
    $sandboxHelperSource = Join-Path $package.InstallLocation 'app\resources\codex-windows-sandbox-setup.exe'
    $commandRunnerSource = Join-Path $package.InstallLocation 'app\resources\codex-command-runner.exe'
    $codeModeHostSource = Join-Path $package.InstallLocation 'app\resources\codex-code-mode-host.exe'
    if (-not (Test-Path -LiteralPath $source)) { throw "Desktop app-server binary not found: $source" }
    if (-not (Test-Path -LiteralPath $sandboxHelperSource)) {
        throw "Desktop sandbox helper binary not found: $sandboxHelperSource"
    }
    if (-not (Test-Path -LiteralPath $commandRunnerSource)) {
        throw "Desktop command runner binary not found: $commandRunnerSource"
    }
    if (-not (Test-Path -LiteralPath $codeModeHostSource)) {
        throw "Desktop code-mode host binary not found: $codeModeHostSource"
    }
    New-Item -ItemType Directory -Force -Path $RuntimeDir | Out-Null
    $sourceHash = (Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash.ToLowerInvariant()
    $destination = Join-Path $RuntimeDir ("codex-app-server-{0}.exe" -f $sourceHash.Substring(0, 16))
    $copyRequired = -not (Test-Path -LiteralPath $destination)
    if (-not $copyRequired) {
        $destinationHash = (Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash.ToLowerInvariant()
        $copyRequired = $destinationHash -ne $sourceHash
    }
    if ($copyRequired) {
        $temporary = "$destination.$PID.tmp"
        Copy-Item -LiteralPath $source -Destination $temporary -Force
        $temporaryHash = (Get-FileHash -LiteralPath $temporary -Algorithm SHA256).Hash.ToLowerInvariant()
        if ($temporaryHash -ne $sourceHash) {
            Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue
            throw 'Desktop app-server cache copy failed its SHA-256 check.'
        }
        Move-Item -LiteralPath $temporary -Destination $destination -Force
    }
    Write-LauncherLog "Desktop app-server cache verified sha256=$sourceHash"

    # A copied app-server cannot execute the helper directly from the protected
    # WindowsApps directory. Cache the same-package helper beside it so Windows
    # executable lookup finds an accessible, version-matched binary.
    $sandboxHelperHash = (Get-FileHash -LiteralPath $sandboxHelperSource -Algorithm SHA256).Hash.ToLowerInvariant()
    $sandboxHelperDestination = Join-Path $RuntimeDir 'codex-windows-sandbox-setup.exe'
    $sandboxHelperCopyRequired = -not (Test-Path -LiteralPath $sandboxHelperDestination)
    if (-not $sandboxHelperCopyRequired) {
        $cachedSandboxHelperHash = (Get-FileHash -LiteralPath $sandboxHelperDestination -Algorithm SHA256).Hash.ToLowerInvariant()
        $sandboxHelperCopyRequired = $cachedSandboxHelperHash -ne $sandboxHelperHash
    }
    if ($sandboxHelperCopyRequired) {
        $sandboxHelperTemporary = "$sandboxHelperDestination.$PID.tmp"
        Copy-Item -LiteralPath $sandboxHelperSource -Destination $sandboxHelperTemporary -Force
        $sandboxHelperTemporaryHash = (Get-FileHash -LiteralPath $sandboxHelperTemporary -Algorithm SHA256).Hash.ToLowerInvariant()
        if ($sandboxHelperTemporaryHash -ne $sandboxHelperHash) {
            Remove-Item -LiteralPath $sandboxHelperTemporary -Force -ErrorAction SilentlyContinue
            throw 'Desktop sandbox helper cache copy failed its SHA-256 check.'
        }
        Move-Item -LiteralPath $sandboxHelperTemporary -Destination $sandboxHelperDestination -Force
    }
    Write-LauncherLog "Desktop sandbox helper cache verified sha256=$sandboxHelperHash"
    $commandRunnerHash = (Get-FileHash -LiteralPath $commandRunnerSource -Algorithm SHA256).Hash.ToLowerInvariant()
    $commandRunnerDestination = Join-Path $RuntimeDir 'codex-command-runner.exe'
    $commandRunnerCopyRequired = -not (Test-Path -LiteralPath $commandRunnerDestination)
    if (-not $commandRunnerCopyRequired) {
        $cachedCommandRunnerHash = (Get-FileHash -LiteralPath $commandRunnerDestination -Algorithm SHA256).Hash.ToLowerInvariant()
        $commandRunnerCopyRequired = $cachedCommandRunnerHash -ne $commandRunnerHash
    }
    if ($commandRunnerCopyRequired) {
        $commandRunnerTemporary = "$commandRunnerDestination.$PID.tmp"
        Copy-Item -LiteralPath $commandRunnerSource -Destination $commandRunnerTemporary -Force
        $commandRunnerTemporaryHash = (Get-FileHash -LiteralPath $commandRunnerTemporary -Algorithm SHA256).Hash.ToLowerInvariant()
        if ($commandRunnerTemporaryHash -ne $commandRunnerHash) {
            Remove-Item -LiteralPath $commandRunnerTemporary -Force -ErrorAction SilentlyContinue
            throw 'Desktop command runner cache copy failed its SHA-256 check.'
        }
        Move-Item -LiteralPath $commandRunnerTemporary -Destination $commandRunnerDestination -Force
    }
    Write-LauncherLog "Desktop command runner cache verified sha256=$commandRunnerHash"
    $codeModeHostHash = (Get-FileHash -LiteralPath $codeModeHostSource -Algorithm SHA256).Hash.ToLowerInvariant()
    $codeModeHostDestination = Join-Path $RuntimeDir 'codex-code-mode-host.exe'
    $codeModeHostCopyRequired = -not (Test-Path -LiteralPath $codeModeHostDestination)
    if (-not $codeModeHostCopyRequired) {
        $cachedCodeModeHostHash = (Get-FileHash -LiteralPath $codeModeHostDestination -Algorithm SHA256).Hash.ToLowerInvariant()
        $codeModeHostCopyRequired = $cachedCodeModeHostHash -ne $codeModeHostHash
    }
    if ($codeModeHostCopyRequired) {
        $codeModeHostTemporary = "$codeModeHostDestination.$PID.tmp"
        Copy-Item -LiteralPath $codeModeHostSource -Destination $codeModeHostTemporary -Force
        $codeModeHostTemporaryHash = (Get-FileHash -LiteralPath $codeModeHostTemporary -Algorithm SHA256).Hash.ToLowerInvariant()
        if ($codeModeHostTemporaryHash -ne $codeModeHostHash) {
            Remove-Item -LiteralPath $codeModeHostTemporary -Force -ErrorAction SilentlyContinue
            throw 'Desktop code-mode host cache copy failed its SHA-256 check.'
        }
        Move-Item -LiteralPath $codeModeHostTemporary -Destination $codeModeHostDestination -Force
    }
    Write-LauncherLog "Desktop code-mode host cache verified sha256=$codeModeHostHash"
    return $destination
}

try {
    Write-LauncherLog "START dry_run=$DryRun no_launch=$NoLaunch"
    if (-not (Test-Path -LiteralPath $Python)) { throw "Python runtime not found: $Python" }
    if (-not (Test-Path -LiteralPath $RuntimeTool)) { throw "Runtime helper not found: $RuntimeTool" }
    if (-not (Test-Path -LiteralPath $GateMonitor)) { throw "Desktop gate monitor not found: $GateMonitor" }
    if (-not (Test-Path -LiteralPath $HookTrustTool)) { throw "Hook trust helper not found: $HookTrustTool" }
    if (-not (Test-Path -LiteralPath $HookTrustManifest)) { throw "Hook trust manifest not found: $HookTrustManifest" }
    if (-not (Test-Path -LiteralPath $GatewayProfilePath)) { throw "Gateway profile not found: $GatewayProfilePath" }
    if (-not (Test-Path -LiteralPath $GlobalLoopModeTool)) { throw "Global LOOP mode tool not found: $GlobalLoopModeTool" }
    $Gateway = Get-Content -LiteralPath $GatewayProfilePath -Raw -Encoding UTF8 | ConvertFrom-Json

    $globalModeAction = if ($DryRun) { 'status' } else { 'activate' }
    & $Python -B $GlobalLoopModeTool $globalModeAction --root $GlobalLoopControlRoot `
        --codex-home (Join-Path $env:USERPROFILE '.codex') | Out-Null
    if ($LASTEXITCODE -ne 0) {
        throw "Desktop-wide LOOP mode action failed: $globalModeAction"
    }
    Write-LauncherLog "Desktop-wide LOOP mode action completed: $globalModeAction"

    Ensure-Gateway

    $desktopAppServer = Get-DesktopAppServerCopy
    $hookTrustReport = Join-Path $RuntimeDir 'hook-trust.json'
    & $Python -B $HookTrustTool --root $Root --codex-exe $desktopAppServer `
        --manifest $HookTrustManifest --global-config $GlobalConfig --auth $AuthPath `
        --json-out $hookTrustReport | Out-Null
    if ($LASTEXITCODE -ne 0) {
        throw 'Desktop hook trust verification failed; no unreviewed hooks were trusted.'
    }
