        '--interval', '5'
    ) -WorkingDirectory $Root -WindowStyle Hidden
    Write-LauncherLog 'Desktop runtime supervisor requested'

    Start-Process -FilePath $supervisorExe -ArgumentList @(
        '-B', $GateMonitor,
        '--root', $Root,
        '--python', $Python,
        '--codex-exe', $desktopAppServer,
        '--probe-dir', (Join-Path $Root 'state\probes')
    ) -WorkingDirectory $Root -WindowStyle Hidden
    Write-LauncherLog 'Desktop long-gate monitor requested (single-instance lock protected)'

    $sidecars = Wait-Sidecars
    Write-LauncherLog ("Desktop sidecars ready supervisor_pid={0} gate_monitor_pid={1} runtime_healthy={2}" -f `
        $sidecars.supervisor_pid, $sidecars.gate_monitor_pid, $sidecars.runtime_healthy)

    if (-not $NoLaunch) {
        $encodedRoot = [Uri]::EscapeDataString($Root)
        $uri = "codex://new?path=$encodedRoot"
        Start-Process $uri
        Write-LauncherLog "Codex Desktop URI opened: $uri"
        Start-Sleep -Milliseconds 750
        if (Show-CodexDesktop) {
