            $item = Get-Item -Force -LiteralPath $cursor
            if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
                throw "Reparse points are not allowed in managed paths: $cursor"
            }
        }
        if ($cursor.Equals($Root, [StringComparison]::OrdinalIgnoreCase)) { break }
        $parent = Split-Path -Parent $cursor
        if ([string]::IsNullOrWhiteSpace($parent) -or $parent -eq $cursor) {
            throw "Could not prove managed path ancestry: $resolved"
        }
        $cursor = $parent
    }
    return $resolved
}

function Assert-TreeHasNoReparsePoint([string]$Path) {
    $resolved = Assert-NoReparsePoint $Path
    foreach ($item in Get-ChildItem -Force -Recurse -LiteralPath $resolved) {
        if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
            throw "Reparse points are not allowed in configuration templates: $($item.FullName)"
        }
        if ($item.Name -eq '__pycache__' -or $item.Extension -in @('.pyc', '.pyo')) {
            throw "Python cache files are not allowed in configuration templates: $($item.FullName)"
        }
    }
    return $resolved
}

function Assert-MirroredDirectory([string]$Source, [string]$Target) {
    if (-not (Test-Path -LiteralPath $Target -PathType Container)) {
        throw "The public repository is incomplete; missing tracked directory: $Target"
    }
    Assert-TreeHasNoReparsePoint $Source | Out-Null
    Assert-TreeHasNoReparsePoint $Target | Out-Null
    $sourcePrefix = $Source.TrimEnd('\').Length
    $targetPrefix = $Target.TrimEnd('\').Length
    $sourceFiles = @{}
    foreach ($file in Get-ChildItem -LiteralPath $Source -Recurse -Force -File) {
        $relative = $file.FullName.Substring($sourcePrefix).TrimStart('\')
        $sourceFiles[$relative] = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash
    }
    $targetFiles = @{}
    foreach ($file in Get-ChildItem -LiteralPath $Target -Recurse -Force -File) {
        $relative = $file.FullName.Substring($targetPrefix).TrimStart('\')
        $targetFiles[$relative] = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash
    }
    $sourceNames = @(($sourceFiles.Keys | Sort-Object)) -join "`n"
    $targetNames = @(($targetFiles.Keys | Sort-Object)) -join "`n"
    if ($sourceNames -ne $targetNames) {
        throw "Tracked configuration directory has missing or extra files: $Target"
    }
    foreach ($relative in $sourceFiles.Keys) {
        if ($sourceFiles[$relative] -ne $targetFiles[$relative]) {
            throw "Tracked configuration file differs from its staging source: $(Join-Path $Target $relative)"
        }
    }
}

function Invoke-Checked([string]$FilePath, [string[]]$Arguments) {
    & $FilePath @Arguments
    if ($LASTEXITCODE -ne 0) {
        throw "Command failed ($LASTEXITCODE): $FilePath $($Arguments -join ' ')"
    }
}

function Replace-TemplateValue($Value, [hashtable]$Replacements) {
    if ($Value -is [string]) {
        foreach ($key in $Replacements.Keys) {
            $Value = $Value.Replace($key, [string]$Replacements[$key])
        }
        return $Value
    }
    if ($Value -is [System.Collections.IList]) {
        $result = @()
        foreach ($item in $Value) { $result += ,(Replace-TemplateValue $item $Replacements) }
        return $result
    }
    if ($null -ne $Value -and $Value.PSObject.Properties.Count -gt 0) {
        $result = [ordered]@{}
        foreach ($property in $Value.PSObject.Properties) {
            $result[$property.Name] = Replace-TemplateValue $property.Value $Replacements
        }
        return [pscustomobject]$result
    }
    return $Value
}

